    scanf("%lld", &num);

    recursive(num, 0);

    printf("%d\n", ans);

    return 0;
}

void recursive(long long num, int count) {
    if(num == 1) {
        ans = MIN(ans, count);
        return;
    }

    if(num % 2 == 0) {
        recursive(num / 2, count + 1);
    } else {
        recursive(num + 1, count + 1);
        recursive(num - 1, count + 1);
    }
}
